preConditionHook:
// THE TREND-RESUMPTION DAY. The session opened with a leg in one direction
// and has since spent several hours inside a tight range: favour continuation
// in the MORNING leg's direction and block fresh countertrend entries. The
// tighter that midday range against the recent average daily range, the
// stronger the read. T01-07 previews the pattern in one sentence and T25-03
// is the chapter version with the tight-range fraction; same rule, T25-03's
// numbers.
//
// A NAMED BROOKS SETUP, so the parts are INLINED rather than referenced, as
// the corpus does with composites: the morning-leg latch is
// MorningLegDirection's (depends_on_keys), and AverageDailyRange is the
// corpus's session primitive, same text as its own file. The leg latch here
// carries NO ATR threshold -- the merged rule states the direction as the
// sign of close minus session open at openBars and nothing more -- so a pane
// wanting the strong-leg form ANDs MorningLegDirection alongside.
//
// THE MIDDAY WINDOW starts at the leg bar, not at the session open: midHigh
// and midLow are re-seeded on the bar where barsIn reaches openBars and grow
// from there, and midBars counts the bars since. So the range measured is the
// action AFTER the morning leg, which is what the pattern is about.
//
// T25-03's page-454 caveat -- that the midday action can be a weakly trending
// countertrend drift rather than a flat range -- is NOT mechanized;
// tightRangeFraction is the proxy for both forms and should be LOOSENED
// rather than special-cased.
//
// Mirrored: the long side wants an up morning leg, the short a down one. A
// dead-flat leg (close == sessOpen at the leg bar) leaves mld at 0 and
// neither side can fire, so no sign has to be invented for zero.
//
// Compared, never divided. The dayLookback guard WRAPS the date read rather
// than being ANDed with it, because EasyLanguage does not short-circuit and
// the twins must touch the same history.
//
// SESSION MODEL, per the standing decision: the twin's date > date[1],
// mirrored as day_of(ctx.Time(0)) > day_of(ctx.Time(1)); barsIn is 1 on the
// session's first bar. The latch and the accumulate tests sit OUTSIDE the
// session if/else so that openBars = 1 still latches on the first bar.
// Intraday bars only.
//
// Deepest bar touched: maxScanBars + 1.
if (day_of(ctx.Time(0)) > day_of(ctx.Time(1))) {
    barsIn = 1;
    sessOpen = open[0];
    mld = 0;
    midHigh = high[0];
    midLow = low[0];
    midBars = 0;
} else {
    barsIn = barsIn + 1;
}
if (el_eq((double)barsIn, openBars)) {
    midHigh = high[0];
    midLow = low[0];
    midBars = 0;
    if (el_gt(close[0], sessOpen)) mld = 1;
    if (el_lt(close[0], sessOpen)) mld = -1;
}
if (el_gt((double)barsIn, openBars)) {
    midBars = midBars + 1;
    if (el_gt(high[0], midHigh)) midHigh = high[0];
    if (el_lt(low[0], midLow)) midLow = low[0];
}
adrSum = 0.0;
adrDays = 0;
dHi = 0.0;
dLo = 0.0;
dOpen = false;
for (int kk = 1; kk <= (int)maxScanBars; ++kk) {
    if (el_lt((double)adrDays, dayLookback)) {
        if (day_of(ctx.Time(kk)) != day_of(ctx.Time(0))) {
            if (!dOpen) {
                dHi = high[kk];
                dLo = low[kk];
                dOpen = true;
            } else {
                if (el_gt(high[kk], dHi)) dHi = high[kk];
                if (el_lt(low[kk], dLo)) dLo = low[kk];
            }
            if (day_of(ctx.Time(kk + 1)) != day_of(ctx.Time(kk))) {
                adrSum = adrSum + (dHi - dLo);
                adrDays = adrDays + 1;
                dOpen = false;
            }
        }
    }
}
adrReady = el_ge((double)adrDays, dayLookback);
if (adrReady) {
    adr = adrSum / dayLookback;
} else {
    adr = 0.0;
}
resumeUp = (mld == 1) && el_ge((double)midBars, minMiddayBars) && adrReady && el_le(midHigh - midLow, tightRangeFraction * adr);
resumeDn = (mld == -1) && el_ge((double)midBars, minMiddayBars) && adrReady && el_le(midHigh - midLow, tightRangeFraction * adr);
